// QML module "AppDimens 1.0", the AppDimens way: AppDimens.sdp(16), ad.asdp(280) — reactive in bindings.
//   AppDimens     singleton (QML wrapper over the global C++ scope `AppDimensCore`)
//   DimensScope   per-window scope (QML wrapper over `DimensScopeCore`)
// The wrappers live in src/qml (generated by tools/gen_properties.py) and are compiled in as resources.
#include "appdimens/appdimens_qt.hpp"

#include <QQmlEngine>
#include <QUrl>

static void appdimensInitQmlResources() { Q_INIT_RESOURCE(appdimens_qml); }

namespace AppDimens {

void Scope::registerQmlTypes(const char *uri) {
    appdimensInitQmlResources();
    // C++ cores in a private module, so the wrappers do not import their own module.
    static const char *const core = "AppDimens.Core";
    qmlRegisterSingletonType<Scope>(core, 1, 0, "AppDimensCore", [](QQmlEngine *, QJSEngine *) -> QObject * {
        Scope *g = Scope::global();
        QQmlEngine::setObjectOwnership(g, QQmlEngine::CppOwnership);
        return g;
    });
    qmlRegisterType<Scope>(core, 1, 0, "DimensScopeCore");
    qmlRegisterSingletonType(QUrl(QStringLiteral("qrc:/appdimens/AppDimens.qml")), uri, 1, 0, "AppDimens");
    qmlRegisterType(QUrl(QStringLiteral("qrc:/appdimens/DimensScope.qml")), uri, 1, 0, "DimensScope");
}

} // namespace AppDimens
